repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('rovers', 24), ('rovers', 13), ('city', 46), ('town', 45), ('united', 38), ('rovers', 56)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.ordering.py:
"""Codes of fixtures in order."""


def ranked_codes(fixtures):
    """Return the goals of each fixture as a text code, from the lowest number to the highest."""
    return sorted(str(x.goals) for x in fixtures)


def code_of(fixture):
    """Return the text code of one fixture."""
    return str(fixture.goals)


def club_names(fixtures):
    """Return the distinct club values, in first-seen order."""
    names = []
    for x in fixtures:
        if x.club not in names:
            names.append(x.club)
    return names

repo.tests/test_visible.py:
from fixtures import Fixture
from ordering import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Fixture("a", 10), Fixture("b", 9)]) == ["9", "10"]


def test_single_digits():
    assert ranked_codes([Fixture("a", 3), Fixture("b", 1), Fixture("c", 2)]) == ["1", "2", "3"]
